   258                  /* If this is the maker note tag, update it. */
   259                  if ((e->tag == EXIF_TAG_MAKER_NOTE) && data->priv->md) {
   260                          /* TODO: this is using the wrong ExifMem to free e->data */
   261                          exif_mem_free (data->priv->mem, e->data);
   262                          e->data = NULL;
   263                          e->size = 0;
   264                          exif_mnote_data_set_offset (data->priv->md, *ds - 6);
   265                          exif_mnote_data_save (data->priv->md, &e->data, &e->size);
   266                          e->components = e->size;
   267                          if (exif_format_get_size (e->format) != 1) {
   268                                  /* e->format is taken from input code,
   269                                   * but we need to make sure it is a 1 byte
   270                                   * entity due to the multiplication below. */
   271                                  e->format = EXIF_FORMAT_UNDEFINED;
   272                          }
   273                  }
   274          }
   275
   276          exif_set_long  (*d + 6 + offset + 4,
   277                          data->priv->order, e->components);
   278
   279          /*
   280           * Size? If bigger than 4 bytes, the actual data is not in
   281           * the entry but somewhere else.
   282           */
   283          s = exif_format_get_size (e->format) * e->components;
   284          if (s > 4) {
   285                  unsigned char *t;
   286                  doff = *ds - 6;
   287                  ts = *ds + s;
   288
   289                  /*
   290                   * According to the TIFF specification,
   291                   * the offset must be an even number. If we need to introduce
   292                   * a padding byte, we set it to 0.
   293                   */
   294                  if (s & 1)
   295                          ts++;
   296                  t = exif_mem_realloc (data->priv->mem, *d, ts);
   297                  if (!t) {
   298                          EXIF_LOG_NO_MEMORY (data->priv->log, "ExifData", ts);
   299                          return;
   300                  }
   301                  *d = t;
   302                  *ds = ts;
   303                  exif_set_long (*d + 6 + offset + 8, data->priv->order, doff);
   304                  if (s & 1)
   305                          *(*d + *ds - 1) = '\0';
   306
   307          } else
   308                  doff = offset + 8;
   309
   310          /* Write the data. Fill unneeded bytes with 0. Do not crash with
   311           * e->data is NULL */
   312          if (e->data) {
   313                  unsigned int len = s;
   314                  if (e->size < s) len = e->size;
   315                  memcpy (*d + 6 + doff, e->data, len);
   316          } else {
   317                  memset (*d + 6 + doff, 0, s);
   318          }
   319          if (s < 4)
   320                  memset (*d + 6 + doff + s, 0, (4 - s));
   321  }
